@Test
public void testAutoComplete() {
    List<String> words = Arrays.asList("apple", "apple", "apricot", "banana", "blackberry", "blackberry", "blackberry", "blueberry", "blueberry", "cherry");
    PCollection<String> input = p.apply(Create.of(words));
    PCollection<KV<String, List<CompletionCandidate>>> output = input.apply(new ComputeTopCompletions(2, recursive)).apply(Filter.by(element -> element.getKey().length() <= 2));
    PAssert.that(output).containsInAnyOrder(KV.of("a", parseList("apple:2", "apricot:1")), KV.of("ap", parseList("apple:2", "apricot:1")), KV.of("b", parseList("blackberry:3", "blueberry:2")), KV.of("ba", parseList("banana:1")), KV.of("bl", parseList("blackberry:3", "blueberry:2")), KV.of("c", parseList("cherry:1")), KV.of("ch", parseList("cherry:1")));
    p.run().waitUntilFinish();
}

