@Test
public void differentEnvironmentsThrows() {
    // (impulse.out) -> read -> read.out --> go -> go.out
    //                                   \
    //                                    -> py -> py.out
    // read.out can't be fused with both 'go' and 'py', so we should refuse to create this stage
    QueryablePipeline p = QueryablePipeline.forPrimitivesIn(partialComponents.toBuilder().putTransforms("read", PTransform.newBuilder().putInputs("input", "impulse.out").putOutputs("output", "read.out").build()).putPcollections("read.out", PCollection.newBuilder().setUniqueName("read.out").build()).putTransforms("goTransform", PTransform.newBuilder().putInputs("input", "read.out").putOutputs("output", "go.out").setSpec(FunctionSpec.newBuilder().setUrn(PTransformTranslation.PAR_DO_TRANSFORM_URN).setPayload(ParDoPayload.newBuilder().setDoFn(SdkFunctionSpec.newBuilder().setEnvironmentId("go")).build().toByteString())).build()).putPcollections("go.out", PCollection.newBuilder().setUniqueName("go.out").build()).putTransforms("pyTransform", PTransform.newBuilder().putInputs("input", "read.out").putOutputs("output", "py.out").setSpec(FunctionSpec.newBuilder().setUrn(PTransformTranslation.ASSIGN_WINDOWS_TRANSFORM_URN).setPayload(WindowIntoPayload.newBuilder().setWindowFn(SdkFunctionSpec.newBuilder().setEnvironmentId("py")).build().toByteString())).build()).putPcollections("py.out", PCollection.newBuilder().setUniqueName("py.out").build()).putEnvironments("go", Environment.newBuilder().setUrl("go").build()).putEnvironments("py", Environment.newBuilder().setUrl("py").build()).build());
    Set<PTransformNode> differentEnvironments = p.getPerElementConsumers(PipelineNode.pCollection("read.out", PCollection.newBuilder().setUniqueName("read.out").build()));
    thrown.expect(IllegalArgumentException.class);
    thrown.expectMessage("go");
    thrown.expectMessage("py");
    thrown.expectMessage("same");
    GreedyStageFuser.forGrpcPortRead(p, PipelineNode.pCollection("read.out", PCollection.newBuilder().setUniqueName("read.out").build()), differentEnvironments);
}

