@Test
public void testNodeReplacement() {
    Function<String, String> function = input -> {
        if ("E".equals(input) || "J".equals(input) || "M".equals(input) || "O".equals(input)) {
            return input.toLowerCase();
        }
        checkArgument(!input.toLowerCase().equals(input), "All inputs should be in upper case, got %s. " + "This may indicate calling the function on multiple inputs", input);
        return input;
    };
    MutableNetwork<String, String> network = createNetwork();
    Networks.replaceDirectedNetworkNodes(network, function);
    MutableNetwork<String, String> originalNetwork = createNetwork();
    for (String node : originalNetwork.nodes()) {
        assertEquals(originalNetwork.successors(node).stream().map(function).collect(Collectors.toCollection(HashSet::new)), network.successors(function.apply(node)));
    }
    assertEquals(network.nodes(), originalNetwork.nodes().stream().map(function).collect(Collectors.toCollection(HashSet::new)));
}

