@Test
public void toTransformProto() throws Exception {
    Map<TupleTag<?>, PValue> inputs = new HashMap<>();
    inputs.put(new TupleTag<KV<Long, String>>("mainInputName") {
    }, mainInput);
    inputs.putAll(parDo.getAdditionalInputs());
    PCollectionTuple output = mainInput.apply(parDo);
    SdkComponents sdkComponents = SdkComponents.create();
    sdkComponents.registerEnvironment(Environment.newBuilder().setUrl("java").build());
    // Encode
    RunnerApi.PTransform protoTransform = PTransformTranslation.toProto(AppliedPTransform.<PCollection<KV<Long, String>>, PCollection<Void>, MultiOutput>of("foo", inputs, output.expand(), parDo, p), sdkComponents);
    RunnerApi.Components components = sdkComponents.toComponents();
    RehydratedComponents rehydratedComponents = RehydratedComponents.forComponents(components);
    // Decode
    ParDoPayload parDoPayload = ParDoPayload.parseFrom(protoTransform.getSpec().getPayload());
    for (PCollectionView<?> view : parDo.getSideInputs()) {
        SideInput sideInput = parDoPayload.getSideInputsOrThrow(view.getTagInternal().getId());
        PCollectionView<?> restoredView = PCollectionViewTranslation.viewFromProto(sideInput, view.getTagInternal().getId(), view.getPCollection(), protoTransform, rehydratedComponents);
        assertThat(restoredView.getTagInternal(), equalTo(view.getTagInternal()));
        assertThat(restoredView.getViewFn(), instanceOf(view.getViewFn().getClass()));
        assertThat(restoredView.getWindowMappingFn(), instanceOf(view.getWindowMappingFn().getClass()));
        assertThat(restoredView.getWindowingStrategyInternal(), equalTo(view.getWindowingStrategyInternal().fixDefaults()));
        assertThat(restoredView.getCoderInternal(), equalTo(view.getCoderInternal()));
    }
    String mainInputId = sdkComponents.registerPCollection(mainInput);
    assertThat(ParDoTranslation.getMainInput(protoTransform, components), equalTo(components.getPcollectionsOrThrow(mainInputId)));
    assertThat(ParDoTranslation.getMainInputName(protoTransform), equalTo("mainInputName"));
    // Validate that the timer PCollections are added correctly.
    DoFnSignature signature = DoFnSignatures.signatureForDoFn(parDo.getFn());
    for (String localTimerName : signature.timerDeclarations().keySet()) {
        RunnerApi.PCollection timerPCollection = components.getPcollectionsOrThrow(String.format("foo.%s", localTimerName));
        assertEquals(components.getPcollectionsOrThrow(mainInputId).getIsBounded(), timerPCollection.getIsBounded());
        assertEquals(components.getPcollectionsOrThrow(mainInputId).getWindowingStrategyId(), timerPCollection.getWindowingStrategyId());
        ModelCoders.KvCoderComponents timerKvCoderComponents = ModelCoders.getKvCoderComponents(components.getCodersOrThrow(timerPCollection.getCoderId()));
        Coder<?> timerKeyCoder = CoderTranslation.fromProto(components.getCodersOrThrow(timerKvCoderComponents.keyCoderId()), rehydratedComponents);
        assertEquals(VarLongCoder.of(), timerKeyCoder);
        Coder<?> timerValueCoder = CoderTranslation.fromProto(components.getCodersOrThrow(timerKvCoderComponents.valueCoderId()), rehydratedComponents);
        assertEquals(org.apache.beam.runners.core.construction.Timer.Coder.of(VoidCoder.of()), timerValueCoder);
    }
}

