    assertEquals(new Instant(29), tester.getWatermarkHold());
    assertEquals(new Instant(29), tester.getNextTimer(TimeDomain.EVENT_TIME));
    // Trigger the garbage collection timer.
    tester.advanceInputWatermark(new Instant(30));
