@Test
public void testFlattenInMemoryEvaluator() throws Exception {
    PCollectionNode left = PipelineNode.pCollection("left", PCollection.newBuilder().setUniqueName("left").build());
    PCollectionNode right = PipelineNode.pCollection("right", PCollection.newBuilder().setUniqueName("right").build());
    // Include a root node for a sane-looking graph
    PTransformNode source = PipelineNode.pTransform("source", PTransform.newBuilder().putOutputs("left", left.getId()).putOutputs("right", right.getId()).build());
    PCollectionNode flattened = PipelineNode.pCollection("flat", PCollection.newBuilder().setUniqueName("flat").build());
    PTransformNode flatten = PipelineNode.pTransform("flatten", PTransform.newBuilder().setUniqueName("flatten").putInputs("left", left.getId()).putInputs("right", right.getId()).putOutputs("out", flattened.getId()).setSpec(FunctionSpec.newBuilder().setUrn(PTransformTranslation.FLATTEN_TRANSFORM_URN)).build());
    PortableGraph graph = PortableGraph.forPipeline(RunnerApi.Pipeline.newBuilder().addRootTransformIds(source.getId()).addRootTransformIds(flatten.getId()).setComponents(RunnerApi.Components.newBuilder().putTransforms(source.getId(), source.getTransform()).putPcollections(left.getId(), left.getPCollection()).putPcollections(right.getId(), right.getPCollection()).putTransforms(flatten.getId(), flatten.getTransform()).putPcollections(flattened.getId(), flattened.getPCollection())).build());
    CommittedBundle<Integer> leftBundle = bundleFactory.<Integer>createBundle(left).commit(Instant.now());
    CommittedBundle<Integer> rightBundle = bundleFactory.<Integer>createBundle(right).commit(Instant.now());
    FlattenEvaluatorFactory factory = new FlattenEvaluatorFactory(graph, bundleFactory);
    TransformEvaluator<Integer> leftSideEvaluator = factory.forApplication(flatten, leftBundle);
    TransformEvaluator<Integer> rightSideEvaluator = factory.forApplication(flatten, rightBundle);
    leftSideEvaluator.processElement(WindowedValue.valueInGlobalWindow(1));
    rightSideEvaluator.processElement(WindowedValue.valueInGlobalWindow(-1));
    leftSideEvaluator.processElement(WindowedValue.timestampedValueInGlobalWindow(2, new Instant(1024)));
    leftSideEvaluator.processElement(WindowedValue.valueInGlobalWindow(4, PaneInfo.NO_FIRING));
    rightSideEvaluator.processElement(WindowedValue.valueInGlobalWindow(2, PaneInfo.ON_TIME_AND_ONLY_FIRING));
    rightSideEvaluator.processElement(WindowedValue.timestampedValueInGlobalWindow(-4, new Instant(-4096)));
    TransformResult<Integer> rightSideResult = rightSideEvaluator.finishBundle();
    TransformResult<Integer> leftSideResult = leftSideEvaluator.finishBundle();
    assertThat(getOnlyElement(leftSideResult.getOutputBundles()).commit(Instant.now()), containsInAnyOrder(WindowedValue.timestampedValueInGlobalWindow(2, new Instant(1024)), WindowedValue.valueInGlobalWindow(4, PaneInfo.NO_FIRING), WindowedValue.valueInGlobalWindow(1)));
    assertThat(getOnlyElement(rightSideResult.getOutputBundles()).commit(Instant.now()), containsInAnyOrder(WindowedValue.valueInGlobalWindow(2, PaneInfo.ON_TIME_AND_ONLY_FIRING), WindowedValue.timestampedValueInGlobalWindow(-4, new Instant(-4096)), WindowedValue.valueInGlobalWindow(-1)));
}

@Test
public void testInMemoryEvaluator() throws Exception {
    KvCoder<String, Integer> javaCoder = KvCoder.of(StringUtf8Coder.of(), VarIntCoder.of());
    SdkComponents sdkComponents = SdkComponents.create();
    sdkComponents.registerEnvironment(Environment.newBuilder().setUrl("java").build());
    String windowingStrategyId = sdkComponents.registerWindowingStrategy(WindowingStrategy.globalDefault());
    String coderId = sdkComponents.registerCoder(javaCoder);
    Components.Builder builder = sdkComponents.toComponents().toBuilder();
    String javaWireCoderId = LengthPrefixUnknownCoders.addLengthPrefixedCoder(coderId, builder, false);
    String runnerWireCoderId = LengthPrefixUnknownCoders.addLengthPrefixedCoder(coderId, builder, true);
    RehydratedComponents components = RehydratedComponents.forComponents(builder.build());
    Coder<KV<String, Integer>> javaWireCoder = (Coder<KV<String, Integer>>) components.getCoder(javaWireCoderId);
    Coder<KV<?, ?>> runnerWireCoder = (Coder<KV<?, ?>>) components.getCoder(runnerWireCoderId);
    KV<?, ?> firstFoo = asRunnerKV(javaWireCoder, runnerWireCoder, KV.of("foo", -1));
    KV<?, ?> secondFoo = asRunnerKV(javaWireCoder, runnerWireCoder, KV.of("foo", 1));
    KV<?, ?> thirdFoo = asRunnerKV(javaWireCoder, runnerWireCoder, KV.of("foo", 3));
    KV<?, ?> firstBar = asRunnerKV(javaWireCoder, runnerWireCoder, KV.of("bar", 22));
    KV<?, ?> secondBar = asRunnerKV(javaWireCoder, runnerWireCoder, KV.of("bar", 12));
    KV<?, ?> firstBaz = asRunnerKV(javaWireCoder, runnerWireCoder, KV.of("baz", Integer.MAX_VALUE));
    PTransformNode inputTransform = PipelineNode.pTransform("source", PTransform.newBuilder().putOutputs("out", "values").build());
    PCollectionNode values = PipelineNode.pCollection("values", RunnerApi.PCollection.newBuilder().setUniqueName("values").setCoderId(coderId).setWindowingStrategyId(windowingStrategyId).build());
    PCollectionNode groupedKvs = PipelineNode.pCollection("groupedKvs", RunnerApi.PCollection.newBuilder().setUniqueName("groupedKvs").build());
    PTransformNode groupByKeyOnly = PipelineNode.pTransform("gbko", PTransform.newBuilder().putInputs("input", "values").putOutputs("output", "groupedKvs").setSpec(FunctionSpec.newBuilder().setUrn(DirectGroupByKey.DIRECT_GBKO_URN).build()).build());
    Pipeline pipeline = Pipeline.newBuilder().addRootTransformIds(inputTransform.getId()).addRootTransformIds(groupByKeyOnly.getId()).setComponents(builder.putTransforms(inputTransform.getId(), inputTransform.getTransform()).putTransforms(groupByKeyOnly.getId(), groupByKeyOnly.getTransform()).putPcollections(values.getId(), values.getPCollection()).putPcollections(groupedKvs.getId(), groupedKvs.getPCollection())).build();
    PortableGraph graph = PortableGraph.forPipeline(pipeline);
    CommittedBundle<KV<String, Integer>> inputBundle = bundleFactory.<KV<String, Integer>>createBundle(values).commit(Instant.now());
    TransformEvaluator<KV<?, ?>> evaluator = new GroupByKeyOnlyEvaluatorFactory(graph, pipeline.getComponents(), bundleFactory).forApplication(groupByKeyOnly, inputBundle);
    evaluator.processElement(WindowedValue.valueInGlobalWindow(firstFoo));
    evaluator.processElement(WindowedValue.valueInGlobalWindow(secondFoo));
    evaluator.processElement(WindowedValue.valueInGlobalWindow(thirdFoo));
    evaluator.processElement(WindowedValue.valueInGlobalWindow(firstBar));
    evaluator.processElement(WindowedValue.valueInGlobalWindow(secondBar));
    evaluator.processElement(WindowedValue.valueInGlobalWindow(firstBaz));
    TransformResult<KV<?, ?>> result = evaluator.finishBundle();
    // The input to a GroupByKey is assumed to be a KvCoder
    @SuppressWarnings({ "rawtypes", "unchecked" })
    Coder runnerKeyCoder = ((KvCoder) runnerWireCoder).getKeyCoder();
    CommittedBundle<?> fooBundle = null;
    CommittedBundle<?> barBundle = null;
    CommittedBundle<?> bazBundle = null;
    StructuralKey fooKey = StructuralKey.of(firstFoo.getKey(), runnerKeyCoder);
    StructuralKey barKey = StructuralKey.of(firstBar.getKey(), runnerKeyCoder);
    StructuralKey bazKey = StructuralKey.of(firstBaz.getKey(), runnerKeyCoder);
    for (UncommittedBundle<?> groupedBundle : result.getOutputBundles()) {
        CommittedBundle<?> groupedCommitted = groupedBundle.commit(Instant.now());
        if (fooKey.equals(groupedCommitted.getKey())) {
            fooBundle = groupedCommitted;
        } else if (barKey.equals(groupedCommitted.getKey())) {
            barBundle = groupedCommitted;
        } else if (bazKey.equals(groupedCommitted.getKey())) {
            bazBundle = groupedCommitted;
        } else {
            throw new IllegalArgumentException(String.format("Unknown Key %s", groupedCommitted.getKey()));
        }
    }
    assertThat(fooBundle, contains(new KeyedWorkItemMatcher(KeyedWorkItems.elementsWorkItem(fooKey.getKey(), ImmutableSet.of(WindowedValue.valueInGlobalWindow(firstFoo.getValue()), WindowedValue.valueInGlobalWindow(secondFoo.getValue()), WindowedValue.valueInGlobalWindow(thirdFoo.getValue()))), runnerKeyCoder)));
    assertThat(barBundle, contains(new KeyedWorkItemMatcher<>(KeyedWorkItems.elementsWorkItem(barKey.getKey(), ImmutableSet.of(WindowedValue.valueInGlobalWindow(firstBar.getValue()), WindowedValue.valueInGlobalWindow(secondBar.getValue()))), runnerKeyCoder)));
    assertThat(bazBundle, contains(new KeyedWorkItemMatcher<>(KeyedWorkItems.elementsWorkItem(bazKey.getKey(), ImmutableSet.of(WindowedValue.valueInGlobalWindow(firstBaz.getValue()))), runnerKeyCoder)));
}

