@Test
public void testKeyGroupAndCheckpoint() throws Exception {
    // assign to keyGroup 0
    ByteBuffer key0 = ByteBuffer.wrap(CoderUtils.encodeToByteArray(StringUtf8Coder.of(), "11111111"));
    // assign to keyGroup 1
    ByteBuffer key1 = ByteBuffer.wrap(CoderUtils.encodeToByteArray(StringUtf8Coder.of(), "22222222"));
    FlinkKeyGroupStateInternals<String> allState;
    {
        KeyedStateBackend<ByteBuffer> keyedStateBackend = getKeyedStateBackend(2, new KeyGroupRange(0, 1));
        allState = new FlinkKeyGroupStateInternals<>(StringUtf8Coder.of(), keyedStateBackend);
        BagState<String> valueForNamespace0 = allState.state(NAMESPACE_1, STRING_BAG_ADDR);
        BagState<String> valueForNamespace1 = allState.state(NAMESPACE_2, STRING_BAG_ADDR);
        keyedStateBackend.setCurrentKey(key0);
        valueForNamespace0.add("0");
        valueForNamespace1.add("2");
        keyedStateBackend.setCurrentKey(key1);
        valueForNamespace0.add("1");
        valueForNamespace1.add("3");
        assertThat(valueForNamespace0.read(), Matchers.containsInAnyOrder("0", "1"));
        assertThat(valueForNamespace1.read(), Matchers.containsInAnyOrder("2", "3"));
    }
    ClassLoader classLoader = FlinkKeyGroupStateInternalsTest.class.getClassLoader();
    // 1. scale up
    ByteArrayOutputStream out0 = new ByteArrayOutputStream();
    allState.snapshotKeyGroupState(0, new DataOutputStream(out0));
    DataInputStream in0 = new DataInputStream(new ByteArrayInputStream(out0.toByteArray()));
    {
        KeyedStateBackend<ByteBuffer> keyedStateBackend = getKeyedStateBackend(2, new KeyGroupRange(0, 0));
        FlinkKeyGroupStateInternals<String> state0 = new FlinkKeyGroupStateInternals<>(StringUtf8Coder.of(), keyedStateBackend);
        state0.restoreKeyGroupState(0, in0, classLoader);
        BagState<String> valueForNamespace0 = state0.state(NAMESPACE_1, STRING_BAG_ADDR);
        BagState<String> valueForNamespace1 = state0.state(NAMESPACE_2, STRING_BAG_ADDR);
        assertThat(valueForNamespace0.read(), Matchers.containsInAnyOrder("0"));
        assertThat(valueForNamespace1.read(), Matchers.containsInAnyOrder("2"));
    }
    ByteArrayOutputStream out1 = new ByteArrayOutputStream();
    allState.snapshotKeyGroupState(1, new DataOutputStream(out1));
    DataInputStream in1 = new DataInputStream(new ByteArrayInputStream(out1.toByteArray()));
    {
        KeyedStateBackend<ByteBuffer> keyedStateBackend = getKeyedStateBackend(2, new KeyGroupRange(1, 1));
        FlinkKeyGroupStateInternals<String> state1 = new FlinkKeyGroupStateInternals<>(StringUtf8Coder.of(), keyedStateBackend);
        state1.restoreKeyGroupState(1, in1, classLoader);
        BagState<String> valueForNamespace0 = state1.state(NAMESPACE_1, STRING_BAG_ADDR);
        BagState<String> valueForNamespace1 = state1.state(NAMESPACE_2, STRING_BAG_ADDR);
        assertThat(valueForNamespace0.read(), Matchers.containsInAnyOrder("1"));
        assertThat(valueForNamespace1.read(), Matchers.containsInAnyOrder("3"));
    }
    // 2. scale down
    {
        KeyedStateBackend<ByteBuffer> keyedStateBackend = getKeyedStateBackend(2, new KeyGroupRange(0, 1));
        FlinkKeyGroupStateInternals<String> newAllState = new FlinkKeyGroupStateInternals<>(StringUtf8Coder.of(), keyedStateBackend);
        in0.reset();
        in1.reset();
        newAllState.restoreKeyGroupState(0, in0, classLoader);
        newAllState.restoreKeyGroupState(1, in1, classLoader);
        BagState<String> valueForNamespace0 = newAllState.state(NAMESPACE_1, STRING_BAG_ADDR);
        BagState<String> valueForNamespace1 = newAllState.state(NAMESPACE_2, STRING_BAG_ADDR);
        assertThat(valueForNamespace0.read(), Matchers.containsInAnyOrder("0", "1"));
        assertThat(valueForNamespace1.read(), Matchers.containsInAnyOrder("2", "3"));
    }
}

/**
 * Creates a {@link UnboundedSourceWrapper} that has one or multiple readers per source. If
 * numSplits > numTasks the source has one source will manage multiple readers.
 */
@Test
public void testValueEmission() throws Exception {
    final int numElementsPerShard = 20;
    final Object checkpointLock = new Object();
    PipelineOptions options = PipelineOptionsFactory.create();
    final long[] numElementsReceived = { 0L };
    final int[] numWatermarksReceived = { 0 };
    // this source will emit exactly NUM_ELEMENTS for each parallel reader,
    // afterwards it will stall. We check whether we also receive NUM_ELEMENTS
    // elements later.
    TestCountingSource source = new TestCountingSource(numElementsPerShard).withFixedNumSplits(numSplits);
    for (int subtaskIndex = 0; subtaskIndex < numTasks; subtaskIndex++) {
        UnboundedSourceWrapper<KV<Integer, Integer>, TestCountingSource.CounterMark> flinkWrapper = new UnboundedSourceWrapper<>("stepName", options, source, numTasks);
        // the source wrapper will only request as many splits as there are tasks and the source
        // will create at most numSplits splits
        assertEquals(numSplits, flinkWrapper.getSplitSources().size());
        StreamSource<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>, UnboundedSourceWrapper<KV<Integer, Integer>, TestCountingSource.CounterMark>> sourceOperator = new StreamSource<>(flinkWrapper);
        AbstractStreamOperatorTestHarness<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>> testHarness = new AbstractStreamOperatorTestHarness<>(sourceOperator, numTasks, /* max parallelism */
        numTasks, /* parallelism */
        subtaskIndex);
        testHarness.setProcessingTime(System.currentTimeMillis());
        // start a thread that advances processing time, so that we eventually get the final
        // watermark which is only updated via a processing-time trigger
        Thread processingTimeUpdateThread = new Thread() {

            @Override
            public void run() {
                while (true) {
                    try {
                        synchronized (testHarness.getCheckpointLock()) {
                            testHarness.setProcessingTime(System.currentTimeMillis());
                        }
                        Thread.sleep(1000);
                    } catch (Exception e) {
                        break;
                    }
                }
            }
        };
        processingTimeUpdateThread.start();
        testHarness.setTimeCharacteristic(TimeCharacteristic.EventTime);
        try {
            testHarness.open();
            sourceOperator.run(checkpointLock, new TestStreamStatusMaintainer(), new Output<StreamRecord<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>>>() {

                private boolean hasSeenMaxWatermark = false;

                @Override
                public void emitWatermark(Watermark watermark) {
                    // we get this when there is no more data
                    // it can happen that we get the max watermark several times, so guard against
                    // this
                    if (!hasSeenMaxWatermark && watermark.getTimestamp() >= BoundedWindow.TIMESTAMP_MAX_VALUE.getMillis()) {
                        numWatermarksReceived[0]++;
                        hasSeenMaxWatermark = true;
                    }
                }

                @Override
                public <X> void collect(OutputTag<X> outputTag, StreamRecord<X> streamRecord) {
                    collect((StreamRecord) streamRecord);
                }

                @Override
                public void emitLatencyMarker(LatencyMarker latencyMarker) {
                }

                @Override
                public void collect(StreamRecord<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>> windowedValueStreamRecord) {
                    numElementsReceived[0]++;
                }

                @Override
                public void close() {
                }
            });
        } catch (SuccessException e) {
            processingTimeUpdateThread.interrupt();
            processingTimeUpdateThread.join();
            // success, continue for the other subtask indices
        }
    }
    // verify that we get the expected count across all subtasks
    assertEquals(numElementsPerShard * numSplits, numElementsReceived[0]);
    // and that we get as many final watermarks as there are subtasks
    assertEquals(numTasks, numWatermarksReceived[0]);
}

/**
 * Creates a {@link UnboundedSourceWrapper} that has one or multiple readers per source. If
 * numSplits > numTasks the source has one source will manage multiple readers.
 *
 * <p>This test verifies that watermark are correctly forwarded.
 */
@Test(timeout = 30_000)
public void testWatermarkEmission() throws Exception {
    final int numElements = 500;
    final Object checkpointLock = new Object();
    PipelineOptions options = PipelineOptionsFactory.create();
    // this source will emit exactly NUM_ELEMENTS across all parallel readers,
    // afterwards it will stall. We check whether we also receive NUM_ELEMENTS
    // elements later.
    TestCountingSource source = new TestCountingSource(numElements);
    UnboundedSourceWrapper<KV<Integer, Integer>, TestCountingSource.CounterMark> flinkWrapper = new UnboundedSourceWrapper<>("stepName", options, source, numSplits);
    assertEquals(numSplits, flinkWrapper.getSplitSources().size());
    final StreamSource<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>, UnboundedSourceWrapper<KV<Integer, Integer>, TestCountingSource.CounterMark>> sourceOperator = new StreamSource<>(flinkWrapper);
    final AbstractStreamOperatorTestHarness<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>> testHarness = new AbstractStreamOperatorTestHarness<>(sourceOperator, numTasks, /* max parallelism */
    numTasks, /* parallelism */
    0);
    testHarness.setProcessingTime(Instant.now().getMillis());
    testHarness.setTimeCharacteristic(TimeCharacteristic.EventTime);
    final ConcurrentLinkedQueue<Object> caughtExceptions = new ConcurrentLinkedQueue<>();
    // use the AtomicBoolean just for the set()/get() functionality for communicating
    // with the outer Thread
    final AtomicBoolean seenWatermark = new AtomicBoolean(false);
    Thread sourceThread = new Thread(() -> {
        try {
            testHarness.open();
            sourceOperator.run(checkpointLock, new TestStreamStatusMaintainer(), new Output<StreamRecord<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>>>() {

                @Override
                public void emitWatermark(Watermark watermark) {
                    if (watermark.getTimestamp() >= numElements / 2) {
                        seenWatermark.set(true);
                    }
                }

                @Override
                public <X> void collect(OutputTag<X> outputTag, StreamRecord<X> streamRecord) {
                }

                @Override
                public void emitLatencyMarker(LatencyMarker latencyMarker) {
                }

                @Override
                public void collect(StreamRecord<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>> windowedValueStreamRecord) {
                }

                @Override
                public void close() {
                }
            });
        } catch (Exception e) {
            System.out.println("Caught exception: " + e);
            caughtExceptions.add(e);
        }
    });
    sourceThread.start();
    while (true) {
        if (!caughtExceptions.isEmpty()) {
            fail("Caught exception(s): " + Joiner.on(",").join(caughtExceptions));
        }
        if (seenWatermark.get()) {
            break;
        }
        Thread.sleep(10);
        // need to advance this so that the watermark timers in the source wrapper fire
        testHarness.setProcessingTime(Instant.now().getMillis());
    }
    sourceOperator.cancel();
    sourceThread.join();
}

/**
 * Verify that snapshot/restore work as expected. We bring up a source and cancel after seeing a
 * certain number of elements. Then we snapshot that source, bring up a completely new source
 * that we restore from the snapshot and verify that we see all expected elements in the end.
 */
@Test
public void testRestore() throws Exception {
    final int numElements = 20;
    final Object checkpointLock = new Object();
    PipelineOptions options = PipelineOptionsFactory.create();
    // this source will emit exactly NUM_ELEMENTS across all parallel readers,
    // afterwards it will stall. We check whether we also receive NUM_ELEMENTS
    // elements later.
    TestCountingSource source = new TestCountingSource(numElements);
    UnboundedSourceWrapper<KV<Integer, Integer>, TestCountingSource.CounterMark> flinkWrapper = new UnboundedSourceWrapper<>("stepName", options, source, numSplits);
    assertEquals(numSplits, flinkWrapper.getSplitSources().size());
    StreamSource<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>, UnboundedSourceWrapper<KV<Integer, Integer>, TestCountingSource.CounterMark>> sourceOperator = new StreamSource<>(flinkWrapper);
    AbstractStreamOperatorTestHarness<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>> testHarness = new AbstractStreamOperatorTestHarness<>(sourceOperator, numTasks, /* max parallelism */
    numTasks, /* parallelism */
    0);
    testHarness.setTimeCharacteristic(TimeCharacteristic.EventTime);
    final Set<KV<Integer, Integer>> emittedElements = new HashSet<>();
    boolean readFirstBatchOfElements = false;
    try {
        testHarness.open();
        sourceOperator.run(checkpointLock, new TestStreamStatusMaintainer(), new Output<StreamRecord<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>>>() {

            private int count = 0;

            @Override
            public void emitWatermark(Watermark watermark) {
            }

            @Override
            public <X> void collect(OutputTag<X> outputTag, StreamRecord<X> streamRecord) {
                collect((StreamRecord) streamRecord);
            }

            @Override
            public void emitLatencyMarker(LatencyMarker latencyMarker) {
            }

            @Override
            public void collect(StreamRecord<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>> windowedValueStreamRecord) {
                emittedElements.add(windowedValueStreamRecord.getValue().getValue().getValue());
                count++;
                if (count >= numElements / 2) {
                    throw new SuccessException();
                }
            }

            @Override
            public void close() {
            }
        });
    } catch (SuccessException e) {
        // success
        readFirstBatchOfElements = true;
    }
    assertTrue("Did not successfully read first batch of elements.", readFirstBatchOfElements);
    // draw a snapshot
    OperatorSubtaskState snapshot = testHarness.snapshot(0, 0);
    // test that finalizeCheckpoint on CheckpointMark is called
    final ArrayList<Integer> finalizeList = new ArrayList<>();
    TestCountingSource.setFinalizeTracker(finalizeList);
    testHarness.notifyOfCompletedCheckpoint(0);
    assertEquals(flinkWrapper.getLocalSplitSources().size(), finalizeList.size());
    // create a completely new source but restore from the snapshot
    TestCountingSource restoredSource = new TestCountingSource(numElements);
    UnboundedSourceWrapper<KV<Integer, Integer>, TestCountingSource.CounterMark> restoredFlinkWrapper = new UnboundedSourceWrapper<>("stepName", options, restoredSource, numSplits);
    assertEquals(numSplits, restoredFlinkWrapper.getSplitSources().size());
    StreamSource<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>, UnboundedSourceWrapper<KV<Integer, Integer>, TestCountingSource.CounterMark>> restoredSourceOperator = new StreamSource<>(restoredFlinkWrapper);
    // set parallelism to 1 to ensure that our testing operator gets all checkpointed state
    AbstractStreamOperatorTestHarness<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>> restoredTestHarness = new AbstractStreamOperatorTestHarness<>(restoredSourceOperator, numTasks, /* max parallelism */
    1, /* parallelism */
    0);
    restoredTestHarness.setTimeCharacteristic(TimeCharacteristic.EventTime);
    // restore snapshot
    restoredTestHarness.initializeState(snapshot);
    boolean readSecondBatchOfElements = false;
    // run again and verify that we see the other elements
    try {
        restoredTestHarness.open();
        restoredSourceOperator.run(checkpointLock, new TestStreamStatusMaintainer(), new Output<StreamRecord<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>>>() {

            private int count = 0;

            @Override
            public void emitWatermark(Watermark watermark) {
            }

            @Override
            public <X> void collect(OutputTag<X> outputTag, StreamRecord<X> streamRecord) {
                collect((StreamRecord) streamRecord);
            }

            @Override
            public void emitLatencyMarker(LatencyMarker latencyMarker) {
            }

            @Override
            public void collect(StreamRecord<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>> windowedValueStreamRecord) {
                emittedElements.add(windowedValueStreamRecord.getValue().getValue().getValue());
                count++;
                if (count >= numElements / 2) {
                    throw new SuccessException();
                }
            }

            @Override
            public void close() {
            }
        });
    } catch (SuccessException e) {
        // success
        readSecondBatchOfElements = true;
    }
    assertEquals(Math.max(1, numSplits / numTasks), restoredFlinkWrapper.getLocalSplitSources().size());
    assertTrue("Did not successfully read second batch of elements.", readSecondBatchOfElements);
    // verify that we saw all NUM_ELEMENTS elements
    assertTrue(emittedElements.size() == numElements);
}

