@Test
@SuppressWarnings({ "rawtypes", "unchecked" })
public void testMerge() {
    WindowFn slidingWindows = Sessions.withGapDuration(Duration.millis(10));
    GroupByKeyTranslator.Merge merge = new GroupByKeyTranslator.Merge(slidingWindows, timestampCombiner);
    org.joda.time.Instant key1 = new org.joda.time.Instant(5);
    WindowedValue<KV<String, String>> value1 = WindowedValue.of(KV.of("key1", "value1"), key1, new IntervalWindow(new org.joda.time.Instant(5), new org.joda.time.Instant(10)), PaneInfo.NO_FIRING);
    org.joda.time.Instant key2 = new org.joda.time.Instant(10);
    WindowedValue<KV<String, String>> value2 = WindowedValue.of(KV.of("key2", "value2"), key2, new IntervalWindow(new org.joda.time.Instant(9), new org.joda.time.Instant(14)), PaneInfo.NO_FIRING);
    KV<org.joda.time.Instant, WindowedValue<KV<String, List<String>>>> result1 = merge.fold(KV.<org.joda.time.Instant, WindowedValue<KV<String, List<String>>>>of(null, null), KV.of(key1, value1));
    assertThat(result1.getKey(), equalTo(key1));
    assertThat(result1.getValue().getValue().getValue(), equalTo(Lists.newArrayList("value1")));
    KV<org.joda.time.Instant, WindowedValue<KV<String, List<String>>>> result2 = merge.fold(result1, KV.of(key2, value2));
    assertThat(result2.getKey(), equalTo(timestampCombiner.combine(key1, key2)));
    Collection<? extends BoundedWindow> resultWindows = result2.getValue().getWindows();
    assertThat(resultWindows.size(), equalTo(1));
    IntervalWindow expectedWindow = new IntervalWindow(new org.joda.time.Instant(5), new org.joda.time.Instant(14));
    assertThat(resultWindows.toArray()[0], equalTo(expectedWindow));
    assertThat(result2.getValue().getValue().getValue(), equalTo(Lists.newArrayList("value1", "value2")));
}

@Test
public void testGearpumpSource() {
    GearpumpPipelineOptions options = PipelineOptionsFactory.create().as(GearpumpPipelineOptions.class);
    ValuesSource<TimestampedValue<String>> valuesSource = new ValuesSource<>(TEST_VALUES, TimestampedValue.TimestampedValueCoder.of(StringUtf8Coder.of()));
    SourceForTest<TimestampedValue<String>> sourceForTest = new SourceForTest<>(options, valuesSource);
    sourceForTest.open(null, Instant.EPOCH);
    for (int i = 0; i < TEST_VALUES.size(); i++) {
        TimestampedValue<String> value = TEST_VALUES.get(i);
        // Check the watermark first since the Source will advance when it's opened
        if (i < TEST_VALUES.size() - 1) {
            Instant expectedWaterMark = TranslatorUtils.jodaTimeToJava8Time(value.getTimestamp());
            Assert.assertEquals(expectedWaterMark, sourceForTest.getWatermark());
        } else {
            Assert.assertEquals(Watermark.MAX(), sourceForTest.getWatermark());
        }
        Message expectedMsg = new DefaultMessage(WindowedValue.timestampedValueInGlobalWindow(value, value.getTimestamp()), value.getTimestamp().getMillis());
        Message message = sourceForTest.read();
        Assert.assertEquals(expectedMsg, message);
    }
    Assert.assertNull(sourceForTest.read());
    Assert.assertEquals(Watermark.MAX(), sourceForTest.getWatermark());
}

