public void defaultCodersAllTested() {
    Set<Class<? extends Coder>> defaultCoderTranslators = new DefaultCoderCloudObjectTranslatorRegistrar().classesToTranslators().keySet();
    Set<Class<? extends Coder>> testedClasses = new HashSet<>();
    for (Coder<?> tested : DefaultCoders.data()) {
