@Test
public void testExecutionWithTimer() throws Exception {
    Pipeline p = Pipeline.create();
    final String timerId = "foo";
    final String timerId2 = "foo2";
    p.apply("impulse", Impulse.create()).apply("create", ParDo.of(new DoFn<byte[], KV<String, String>>() {

        @ProcessElement
        public void process(ProcessContext ctxt) {
        }
    })).setCoder(KvCoder.of(StringUtf8Coder.of(), StringUtf8Coder.of())).apply("timer", ParDo.of(new DoFn<KV<String, String>, KV<String, String>>() {

        @TimerId("event")
        private final TimerSpec eventTimerSpec = TimerSpecs.timer(TimeDomain.EVENT_TIME);

        @TimerId("processing")
        private final TimerSpec processingTimerSpec = TimerSpecs.timer(TimeDomain.PROCESSING_TIME);

        @ProcessElement
        public void processElement(ProcessContext context, @TimerId("event") Timer eventTimeTimer, @TimerId("processing") Timer processingTimeTimer) {
            context.output(KV.of("main" + context.element().getKey(), ""));
            eventTimeTimer.set(context.timestamp().plus(1L));
            processingTimeTimer.offset(Duration.millis(2L));
            processingTimeTimer.setRelative();
        }

        @OnTimer("event")
        public void eventTimer(OnTimerContext context, @TimerId("event") Timer eventTimeTimer, @TimerId("processing") Timer processingTimeTimer) {
            context.output(KV.of("event", ""));
            eventTimeTimer.set(context.timestamp().plus(11L));
            processingTimeTimer.offset(Duration.millis(12L));
            processingTimeTimer.setRelative();
        }

        @OnTimer("processing")
        public void processingTimer(OnTimerContext context, @TimerId("event") Timer eventTimeTimer, @TimerId("processing") Timer processingTimeTimer) {
            context.output(KV.of("processing", ""));
            eventTimeTimer.set(context.timestamp().plus(21L));
            processingTimeTimer.offset(Duration.millis(22L));
            processingTimeTimer.setRelative();
        }
    })).// Force the output to be materialized
    apply("gbk", GroupByKey.create());
    RunnerApi.Pipeline pipelineProto = PipelineTranslation.toProto(p);
    FusedPipeline fused = GreedyPipelineFuser.fuse(pipelineProto);
    Optional<ExecutableStage> optionalStage = Iterables.tryFind(fused.getFusedStages(), (ExecutableStage stage) -> !stage.getTimers().isEmpty());
    checkState(optionalStage.isPresent(), "Expected a stage with timers.");
    ExecutableStage stage = optionalStage.get();
    ExecutableProcessBundleDescriptor descriptor = ProcessBundleDescriptors.fromExecutableStage("test_stage", stage, dataServer.getApiServiceDescriptor(), stateServer.getApiServiceDescriptor());
    BundleProcessor processor = controlClient.getProcessor(descriptor.getProcessBundleDescriptor(), descriptor.getRemoteInputDestinations(), stateDelegator);
    Map<Target, Coder<WindowedValue<?>>> outputTargets = descriptor.getOutputTargetCoders();
    Map<Target, Collection<WindowedValue<?>>> outputValues = new HashMap<>();
    Map<Target, RemoteOutputReceiver<?>> outputReceivers = new HashMap<>();
    for (Entry<Target, Coder<WindowedValue<?>>> targetCoder : outputTargets.entrySet()) {
        List<WindowedValue<?>> outputContents = Collections.synchronizedList(new ArrayList<>());
        outputValues.put(targetCoder.getKey(), outputContents);
        outputReceivers.put(targetCoder.getKey(), RemoteOutputReceiver.of(targetCoder.getValue(), outputContents::add));
    }
    String eventTimeInputPCollectionId = null;
    Target eventTimeOutputTarget = null;
    String processingTimeInputPCollectionId = null;
    Target processingTimeOutputTarget = null;
    for (Map<String, ProcessBundleDescriptors.TimerSpec> timerSpecs : descriptor.getTimerSpecs().values()) {
        for (ProcessBundleDescriptors.TimerSpec timerSpec : timerSpecs.values()) {
            if (TimeDomain.EVENT_TIME.equals(timerSpec.getTimerSpec().getTimeDomain())) {
                eventTimeInputPCollectionId = timerSpec.collectionId();
                eventTimeOutputTarget = timerSpec.outputTarget();
            } else if (TimeDomain.PROCESSING_TIME.equals(timerSpec.getTimerSpec().getTimeDomain())) {
                processingTimeInputPCollectionId = timerSpec.collectionId();
                processingTimeOutputTarget = timerSpec.outputTarget();
            } else {
                fail(String.format("Unknown timer specification %s", timerSpec));
            }
        }
    }
    // Set the current system time to a fixed value to get stable values for processing time timer output.
    DateTimeUtils.setCurrentMillisFixed(BoundedWindow.TIMESTAMP_MIN_VALUE.getMillis());
    try (ActiveBundle bundle = processor.newBundle(outputReceivers, StateRequestHandler.unsupported(), BundleProgressHandler.unsupported())) {
        bundle.getInputReceivers().get(stage.getInputPCollection().getId()).accept(WindowedValue.valueInGlobalWindow(kvBytes("X", "X")));
        bundle.getInputReceivers().get(eventTimeInputPCollectionId).accept(WindowedValue.valueInGlobalWindow(timerBytes("Y", 100L)));
        bundle.getInputReceivers().get(processingTimeInputPCollectionId).accept(WindowedValue.valueInGlobalWindow(timerBytes("Z", 200L)));
    }
    Set<Target> timerOutputTargets = ImmutableSet.of(eventTimeOutputTarget, processingTimeOutputTarget);
    Target mainOutputTarget = Iterables.getOnlyElement(Sets.difference(descriptor.getOutputTargetCoders().keySet(), timerOutputTargets));
    assertThat(outputValues.get(mainOutputTarget), containsInAnyOrder(WindowedValue.valueInGlobalWindow(kvBytes("mainX", "")), WindowedValue.valueInGlobalWindow(kvBytes("event", "")), WindowedValue.valueInGlobalWindow(kvBytes("processing", ""))));
    assertThat(timerStructuralValues(outputValues.get(eventTimeOutputTarget)), containsInAnyOrder(timerStructuralValue(WindowedValue.valueInGlobalWindow(timerBytes("X", 1L))), timerStructuralValue(WindowedValue.valueInGlobalWindow(timerBytes("Y", 11L))), timerStructuralValue(WindowedValue.valueInGlobalWindow(timerBytes("Z", 21L)))));
    assertThat(timerStructuralValues(outputValues.get(processingTimeOutputTarget)), containsInAnyOrder(timerStructuralValue(WindowedValue.valueInGlobalWindow(timerBytes("X", 2L))), timerStructuralValue(WindowedValue.valueInGlobalWindow(timerBytes("Y", 12L))), timerStructuralValue(WindowedValue.valueInGlobalWindow(timerBytes("Z", 22L)))));
}

