    assertDeterministic(AvroCoder.of(SchemaBuilder.record("someRecord").fields().name("string").prop(SpecificData.CLASS_PROP, "java.lang.String").type().stringType().noDefault().endRecord()));
    assertNonDeterministic(AvroCoder.of(SchemaBuilder.record("someRecord").fields().name("string").prop(SpecificData.CLASS_PROP, "unknownString").type().stringType().noDefault().endRecord()), reason("someRecord.string", "unknownString is not known to be deterministic"));
    // Custom Strings in Unions
    assertNonDeterministic(AvroCoder.of(SchemaBuilder.unionOf().intType().and().record("someRecord").fields().name("someField").prop(SpecificData.CLASS_PROP, "unknownString").type().stringType().noDefault().endRecord().endUnion()), reason("someRecord.someField", "unknownString is not known to be deterministic"));
}

