@Test
public void testReplaceWithExistingName() {
    pipeline.enableAbandonedNodeEnforcement(false);
    final PCollection<Integer> originalInput = pipeline.apply(Create.of(1, 2, 3));
    class OriginalTransform extends PTransform<PCollection<Integer>, PCollection<Integer>> {

        @Override
        public PCollection<Integer> expand(PCollection<Integer> input) {
            return input.apply("custom_name", Sum.integersGlobally());
        }
    }
    class ReplacementTransform extends PTransform<PCollection<Integer>, PCollection<Integer>> {

        @Override
        public PCollection<Integer> expand(PCollection<Integer> input) {
            return input.apply("custom_name", Max.integersGlobally());
        }
    }
    class ReplacementOverrideFactory implements PTransformOverrideFactory<PCollection<Integer>, PCollection<Integer>, OriginalTransform> {

        @Override
        public PTransformReplacement<PCollection<Integer>, PCollection<Integer>> getReplacementTransform(AppliedPTransform<PCollection<Integer>, PCollection<Integer>, OriginalTransform> transform) {
            return PTransformReplacement.of(originalInput, new ReplacementTransform());
        }

        @Override
        public Map<PValue, ReplacementOutput> mapOutputs(Map<TupleTag<?>, PValue> outputs, PCollection<Integer> newOutput) {
            return Collections.singletonMap(newOutput, ReplacementOutput.of(TaggedPValue.ofExpandedValue(Iterables.getOnlyElement(outputs.values())), TaggedPValue.ofExpandedValue(newOutput)));
        }
    }
    class OriginalMatcher implements PTransformMatcher {

        @Override
        public boolean matches(AppliedPTransform<?, ?, ?> application) {
            return application.getTransform() instanceof OriginalTransform;
        }
    }
    originalInput.apply("original_application", new OriginalTransform());
    pipeline.replaceAll(Collections.singletonList(PTransformOverride.of(new OriginalMatcher(), new ReplacementOverrideFactory())));
