@Test
@Category({ NeedsRunner.class, UsesTestStream.class })
public void testLateDataAccumulating() {
    Instant instant = new Instant(0);
    TestStream<Integer> source = TestStream.create(VarIntCoder.of()).addElements(TimestampedValue.of(1, instant), TimestampedValue.of(2, instant), TimestampedValue.of(3, instant)).advanceWatermarkTo(instant.plus(Duration.standardMinutes(6))).// These elements are late but within the allowed lateness
    addElements(TimestampedValue.of(4, instant), TimestampedValue.of(5, instant)).advanceWatermarkTo(instant.plus(Duration.standardMinutes(20))).// These elements are droppably late
    addElements(TimestampedValue.of(-1, instant), TimestampedValue.of(-2, instant), TimestampedValue.of(-3, instant)).advanceWatermarkToInfinity();
    PCollection<Integer> windowed = p.apply(source).apply(Window.<Integer>into(FixedWindows.of(Duration.standardMinutes(5))).triggering(AfterWatermark.pastEndOfWindow().withEarlyFirings(AfterProcessingTime.pastFirstElementInPane().plusDelayOf(Duration.standardMinutes(2))).withLateFirings(AfterPane.elementCountAtLeast(1))).accumulatingFiredPanes().withAllowedLateness(Duration.standardMinutes(5), ClosingBehavior.FIRE_ALWAYS));
    PCollection<Integer> triggered = windowed.apply(WithKeys.of(1)).apply(GroupByKey.create()).apply(Values.create()).apply(Flatten.iterables());
    PCollection<Long> count = windowed.apply(Combine.globally(Count.<Integer>combineFn()).withoutDefaults());
    PCollection<Integer> sum = windowed.apply(Sum.integersGlobally().withoutDefaults());
    IntervalWindow window = new IntervalWindow(instant, instant.plus(Duration.standardMinutes(5L)));
    PAssert.that(triggered).inFinalPane(window).containsInAnyOrder(1, 2, 3, 4, 5);
    PAssert.that(triggered).inOnTimePane(window).containsInAnyOrder(1, 2, 3);
    PAssert.that(count).inWindow(window).satisfies(input -> {
        for (Long count1 : input) {
            assertThat(count1, allOf(greaterThanOrEqualTo(3L), lessThanOrEqualTo(5L)));
        }
        return null;
    });
    PAssert.that(sum).inWindow(window).satisfies(input -> {
        for (Integer sum1 : input) {
            assertThat(sum1, allOf(greaterThanOrEqualTo(6), lessThanOrEqualTo(15)));
        }
        return null;
    });
    p.run();
}

