    int b = combineFn.getNumBuffers();
    int k = combineFn.getBufferSize();
    long n = this.maxInputSize;
    assertThat("(b-2)2^(b-2) + 1/2 <= eN", (b - 2) * (1 << (b - 2)) + 0.5, Matchers.lessThanOrEqualTo(this.epsilon * n));
