@Test
public void testFormatCompatibleTypes() {
    Multimap<DisplayData.Type, Object> validPairs = ImmutableMultimap.<DisplayData.Type, Object>builder().put(DisplayData.Type.INTEGER, 1234).put(DisplayData.Type.INTEGER, 1234L).put(DisplayData.Type.FLOAT, 123.4f).put(DisplayData.Type.FLOAT, 123.4).put(DisplayData.Type.FLOAT, 1234).put(DisplayData.Type.FLOAT, 1234L).build();
    for (Map.Entry<DisplayData.Type, Object> pair : validPairs.entries()) {
        DisplayData.Type type = pair.getKey();
        Object value = pair.getValue();
        try {
            type.format(value);
        } catch (ClassCastException e) {
            throw new AssertionError(String.format("Failed to format %s for DisplayData.%s", value.getClass().getSimpleName(), type), e);
        }
    }
}

