public void testSideInputWithNestedIterables() {
    final PCollectionView<Iterable<Integer>> view1 = pipeline.apply("CreateVoid1", Create.of((Void) null).withCoder(VoidCoder.of())).apply("OutputOneInteger", ParDo.of(new DoFn<Void, Integer>() {

