/**
 * Tests that a trigger set up prior to a SQL statement still is effective within the SQL
 * statement.
 */
@Test
@Category(UsesTestStream.class)
public void testTriggeredTumble() throws Exception {
    Schema inputSchema = Schema.builder().addInt32Field("f_int").addDateTimeField("f_timestamp").build();
    PCollection<Row> input = pipeline.apply(TestStream.create(inputSchema, SerializableFunctions.identity(), SerializableFunctions.identity()).addElements(Row.withSchema(inputSchema).addValues(1, FORMAT.parseDateTime("2017-01-01 01:01:01")).build(), Row.withSchema(inputSchema).addValues(2, FORMAT.parseDateTime("2017-01-01 01:01:01")).build()).addElements(Row.withSchema(inputSchema).addValues(3, FORMAT.parseDateTime("2017-01-01 01:01:01")).build()).addElements(Row.withSchema(inputSchema).addValues(4, FORMAT.parseDateTime("2017-01-01 01:01:01")).build()).advanceWatermarkToInfinity());
    String sql = "SELECT SUM(f_int) AS f_int_sum FROM PCOLLECTION" + " GROUP BY TUMBLE(f_timestamp, INTERVAL '1' HOUR)";
    Schema outputSchema = Schema.builder().addInt32Field("fn_int_sum").build();
    PCollection<Row> result = input.apply("Triggering", Window.<Row>configure().triggering(Repeatedly.forever(AfterPane.elementCountAtLeast(1))).withAllowedLateness(Duration.ZERO).withOnTimeBehavior(Window.OnTimeBehavior.FIRE_IF_NON_EMPTY).accumulatingFiredPanes()).apply("Windowed Query", SqlTransform.query(sql));
    PAssert.that(result).containsInAnyOrder(TestUtils.RowsBuilder.of(outputSchema).addRows(// first bundle 1+2
    3).addRows(// next bundle 1+2+3
    6).addRows(// next bundle 1+2+3+4)
    10).getRows());
    pipeline.run().waitUntilFinish();
}

