@Test
public void testBuildExpression_date() {
    RexNode rexNode;
    BeamSqlExpression exp;
    Calendar calendar = Calendar.getInstance();
    calendar.setTimeZone(TimeZone.getTimeZone("GMT"));
    calendar.setTime(new Date());
    // CURRENT_DATE
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.CURRENT_DATE, Arrays.asList());
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlCurrentDateExpression);
    // LOCALTIME
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.LOCALTIME, Arrays.asList());
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlCurrentTimeExpression);
    // LOCALTIMESTAMP
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.LOCALTIMESTAMP, Arrays.asList());
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlCurrentTimestampExpression);
    // DATETIME_PLUS
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.DATETIME_PLUS, Arrays.<RexNode>asList(rexBuilder.makeDateLiteral(calendar), rexBuilder.makeIntervalLiteral(BigDecimal.TEN, new SqlIntervalQualifier(TimeUnit.DAY, TimeUnit.DAY, SqlParserPos.ZERO))));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlDatetimePlusExpression);
    // * for intervals
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.MULTIPLY, Arrays.<RexNode>asList(rexBuilder.makeExactLiteral(BigDecimal.ONE), rexBuilder.makeIntervalLiteral(BigDecimal.TEN, new SqlIntervalQualifier(TimeUnit.DAY, TimeUnit.DAY, SqlParserPos.ZERO))));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlIntervalMultiplyExpression);
    // minus for dates
    rexNode = rexBuilder.makeCall(TYPE_FACTORY.createSqlIntervalType(new SqlIntervalQualifier(TimeUnit.DAY, TimeUnit.DAY, SqlParserPos.ZERO)), SqlStdOperatorTable.MINUS, Arrays.asList(rexBuilder.makeTimestampLiteral(Calendar.getInstance(), 1000), rexBuilder.makeTimestampLiteral(Calendar.getInstance(), 1000)));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlDatetimeMinusExpression);
}

