@Test
public void testRoundFunction() {
    // test round functions with operands of type bigint, int,
    // tinyint, smallint, double, decimal
    List<BeamSqlExpression> operands = new ArrayList<>();
    // round(double, double) => double
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 2.0));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 4.0));
    Assert.assertEquals(2.0, new BeamSqlRoundExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    // round(integer,integer) => integer
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, 2));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, 2));
    Assert.assertEquals(2, new BeamSqlRoundExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    // round(long,long) => long
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.BIGINT, 5L));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.BIGINT, 3L));
    Assert.assertEquals(5L, new BeamSqlRoundExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    // round(short) => short
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.SMALLINT, Short.valueOf("4")));
    Assert.assertEquals(SqlFunctions.toShort(4), new BeamSqlRoundExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    // round(long,long) => long
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.BIGINT, 2L));
    Assert.assertEquals(2L, new BeamSqlRoundExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    // round(double, long) => double
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 1.1));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.BIGINT, 1L));
    Assert.assertEquals(1.1, new BeamSqlRoundExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 2.368768));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, 2));
    Assert.assertEquals(2.37, new BeamSqlRoundExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 3.78683686458));
    Assert.assertEquals(4.0, new BeamSqlRoundExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 378.683686458));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, -2));
    Assert.assertEquals(400.0, new BeamSqlRoundExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 378.683686458));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, -1));
    Assert.assertEquals(380.0, new BeamSqlRoundExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    // round(integer, double) => integer
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, 2));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 2.2));
    Assert.assertEquals(2, new BeamSqlRoundExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    // operand with a BeamSqlInputRefExpression
    // to select a column value from row of a row
    operands.clear();
    BeamSqlInputRefExpression ref0 = new BeamSqlInputRefExpression(SqlTypeName.BIGINT, 0);
    operands.add(ref0);
    operands.add(BeamSqlPrimitive.of(SqlTypeName.BIGINT, 2L));
    Assert.assertEquals(1234567L, new BeamSqlRoundExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
}

@Test
public void testPowerFunction() {
    // test power functions with operands of type bigint, int,
    // tinyint, smallint, double, decimal
    List<BeamSqlExpression> operands = new ArrayList<>();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 2.0));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 4.0));
    Assert.assertEquals(16.0, new BeamSqlPowerExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    // power(integer,integer) => long
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, 2));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, 2));
    Assert.assertEquals(4.0, new BeamSqlPowerExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    // power(integer,long) => long
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, 2));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.BIGINT, 3L));
    Assert.assertEquals(8.0, new BeamSqlPowerExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    // power(long,long) => long
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.BIGINT, 2L));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.BIGINT, 2L));
    Assert.assertEquals(4.0, new BeamSqlPowerExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    // power(double, int) => double
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 1.1));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, 1));
    Assert.assertEquals(1.1, new BeamSqlPowerExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    // power(double, long) => double
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 1.1));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.BIGINT, 1L));
    Assert.assertEquals(1.1, new BeamSqlPowerExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
    // power(integer, double) => double
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, 2));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 2.2));
    Assert.assertEquals(Math.pow(2, 2.2), new BeamSqlPowerExpression(operands).evaluate(row, null, BeamSqlExpressionEnvironments.empty()).getValue());
}

