    Schema messageSchema = Schema.builder().addDateTimeField("event_timestamp").addMapField("attributes", VARCHAR, VARCHAR).addRowField("payload", payloadSchema).build();
    PCollection<Row> rows = pipeline.apply("create", Create.timestamped(message(1, map("attr", "val"), "{ \"id\" : 3, \"name\" : \"foo\" }"), message(2, map("bttr", "vbl"), "{ \"name\" : \"baz\", \"id\" : 5 }"), message(3, map("cttr", "vcl"), "{ \"id\" : 7, \"name\" : \"bar\" }"), message(4, map("dttr", "vdl"), "{ \"name\" : \"qaz\", \"id\" : 8 }"))).apply("convert", ParDo.of(PubsubMessageToRow.builder().messageSchema(messageSchema).useDlq(false).build()));
    PAssert.that(rows).containsInAnyOrder(Row.withSchema(messageSchema).addValues(ts(1), map("attr", "val"), row(payloadSchema, 3, "foo")).build(), Row.withSchema(messageSchema).addValues(ts(2), map("bttr", "vbl"), row(payloadSchema, 5, "baz")).build(), Row.withSchema(messageSchema).addValues(ts(3), map("cttr", "vcl"), row(payloadSchema, 7, "bar")).build(), Row.withSchema(messageSchema).addValues(ts(4), map("dttr", "vdl"), row(payloadSchema, 8, "qaz")).build());
