public void testSimpleInsert() throws Exception {
    BeamSqlEnv sqlEnv = BeamSqlEnv.inMemory(new PubsubJsonTableProvider(), new BigQueryTableProvider());
    String createTableString = "CREATE TABLE pubsub_topic (
" + "event_timestamp TIMESTAMP, 
" + "attributes MAP<VARCHAR, VARCHAR>, 
" + "payload ROW< 
" + "             id INTEGER, 
" + "             name VARCHAR 
" + "           > 
" + ") 
" + "TYPE 'pubsub' 
" + "LOCATION '" + pubsub.topicPath() + "' 
" + "TBLPROPERTIES '{ "timestampAttributeKey" : "ts" }'";
    sqlEnv.executeDdl(createTableString);
    String createTableStatement = "CREATE TABLE bq_table( 
" + "   id BIGINT, 
" + "   name VARCHAR 
 " + ") 
" + "TYPE 'bigquery' 
" + "LOCATION '" + bigQuery.tableSpec() + "'";
    sqlEnv.executeDdl(createTableStatement);
    String insertStatement = "INSERT INTO bq_table 
" + "SELECT 
" + "  pubsub_topic.payload.id, 
" + "  pubsub_topic.payload.name 
" + "FROM pubsub_topic";
    BeamSqlRelUtils.toPCollection(pipeline, sqlEnv.parseQuery(insertStatement));
    pipeline.run();
    List<PubsubMessage> messages = ImmutableList.of(message(ts(1), 3, "foo"), message(ts(2), 5, "bar"), message(ts(3), 7, "baz"));
    pubsub.publish(messages);
    bigQuery.assertThatAllRows(SOURCE_SCHEMA).eventually(containsInAnyOrder(row(SOURCE_SCHEMA, 3L, "foo"), row(SOURCE_SCHEMA, 5L, "bar"), row(SOURCE_SCHEMA, 7L, "baz"))).pollFor(Duration.standardMinutes(5));
}

