@Test
public void testWithDefaultBuffer() throws Exception {
    final Collection<BeamFnApi.Elements> values = new ArrayList<>();
    final AtomicBoolean onCompletedWasCalled = new AtomicBoolean();
    CloseableFnDataReceiver<WindowedValue<byte[]>> consumer = BeamFnDataBufferingOutboundObserver.forLocation(OUTPUT_LOCATION, CODER, TestStreams.withOnNext(addToValuesConsumer(values)).withOnCompleted(setBooleanToTrue(onCompletedWasCalled)).build());
    // Test that nothing is emitted till the default buffer size is surpassed.
    consumer.accept(valueInGlobalWindow(new byte[BeamFnDataBufferingOutboundObserver.DEFAULT_BUFFER_LIMIT_BYTES - 50]));
    assertThat(values, empty());
    // Test that when we cross the buffer, we emit.
    consumer.accept(valueInGlobalWindow(new byte[50]));
    assertEquals(messageWithData(new byte[BeamFnDataBufferingOutboundObserver.DEFAULT_BUFFER_LIMIT_BYTES - 50], new byte[50]), Iterables.get(values, 0));
    // Test that nothing is emitted till the default buffer size is surpassed after a reset
    consumer.accept(valueInGlobalWindow(new byte[BeamFnDataBufferingOutboundObserver.DEFAULT_BUFFER_LIMIT_BYTES - 50]));
    assertEquals(1, values.size());
    // Test that when we cross the buffer, we emit.
    consumer.accept(valueInGlobalWindow(new byte[50]));
    assertEquals(messageWithData(new byte[BeamFnDataBufferingOutboundObserver.DEFAULT_BUFFER_LIMIT_BYTES - 50], new byte[50]), Iterables.get(values, 1));
    // Test that when we close with an empty buffer we only have one end of stream
    consumer.close();
    assertEquals(messageWithData(), Iterables.get(values, 2));
    // Test that we can't write to a closed stream.
    try {
        consumer.accept(valueInGlobalWindow(new byte[BeamFnDataBufferingOutboundObserver.DEFAULT_BUFFER_LIMIT_BYTES - 50]));
        fail("Writing after close should be prohibited.");
    } catch (IllegalStateException exn) {
        // expected
    }
    // Test that we can't close a stream twice.
    try {
        consumer.close();
        fail("Closing twice should be prohibited.");
    } catch (IllegalStateException exn) {
        // expected
    }
}

@Test
public void testConfiguredBufferLimit() throws Exception {
    Collection<BeamFnApi.Elements> values = new ArrayList<>();
    AtomicBoolean onCompletedWasCalled = new AtomicBoolean();
    CloseableFnDataReceiver<WindowedValue<byte[]>> consumer = BeamFnDataBufferingOutboundObserver.forLocationWithBufferLimit(100, OUTPUT_LOCATION, CODER, TestStreams.withOnNext(addToValuesConsumer(values)).withOnCompleted(setBooleanToTrue(onCompletedWasCalled)).build());
    // Test that nothing is emitted till the default buffer size is surpassed.
    consumer.accept(valueInGlobalWindow(new byte[51]));
    assertThat(values, empty());
    // Test that when we cross the buffer, we emit.
    consumer.accept(valueInGlobalWindow(new byte[49]));
    assertEquals(messageWithData(new byte[51], new byte[49]), Iterables.get(values, 0));
    // Test that when we close we empty the value, and then the stream terminator as part
    // of the same message
    consumer.accept(valueInGlobalWindow(new byte[1]));
    consumer.close();
    assertEquals(BeamFnApi.Elements.newBuilder(messageWithData(new byte[1])).addData(BeamFnApi.Elements.Data.newBuilder().setInstructionReference(OUTPUT_LOCATION.getInstructionId()).setTarget(OUTPUT_LOCATION.getTarget())).build(), Iterables.get(values, 1));
}

