    PTransformRunnerFactory<Object> startFinishRecorder = (pipelineOptions, beamFnDataClient, beamFnStateClient, pTransformId, pTransform, processBundleInstructionId, pCollections, coders, windowingStrategies, pCollectionIdsToConsumers, addStartFunction, addFinishFunction, splitListener) -> {
        assertThat(processBundleInstructionId.get(), equalTo("999L"));
