@Test
public void testMatch() throws Exception {
    create("testFileAA", "testDataAA".getBytes(StandardCharsets.UTF_8));
    create("testFileA", "testDataA".getBytes(StandardCharsets.UTF_8));
    create("testFileB", "testDataB".getBytes(StandardCharsets.UTF_8));
    // ensure files exist
    assertArrayEquals("testDataAA".getBytes(StandardCharsets.UTF_8), read("testFileAA", 0));
    assertArrayEquals("testDataA".getBytes(StandardCharsets.UTF_8), read("testFileA", 0));
    assertArrayEquals("testDataB".getBytes(StandardCharsets.UTF_8), read("testFileB", 0));
    List<MatchResult> results = fileSystem.match(ImmutableList.of(testPath("testFileA*").toString()));
    assertEquals(Status.OK, Iterables.getOnlyElement(results).status());
    assertThat(Iterables.getOnlyElement(results).metadata(), containsInAnyOrder(Metadata.builder().setResourceId(testPath("testFileAA")).setIsReadSeekEfficient(true).setSizeBytes("testDataAA".getBytes(StandardCharsets.UTF_8).length).build(), Metadata.builder().setResourceId(testPath("testFileA")).setIsReadSeekEfficient(true).setSizeBytes("testDataA".getBytes(StandardCharsets.UTF_8).length).build()));
}

@Test
public void testMatchForNonExistentFile() throws Exception {
    create("testFileAA", "testDataAA".getBytes(StandardCharsets.UTF_8));
    create("testFileBB", "testDataBB".getBytes(StandardCharsets.UTF_8));
    // ensure files exist
    assertArrayEquals("testDataAA".getBytes(StandardCharsets.UTF_8), read("testFileAA", 0));
    assertArrayEquals("testDataBB".getBytes(StandardCharsets.UTF_8), read("testFileBB", 0));
    List<MatchResult> matchResults = fileSystem.match(ImmutableList.of(testPath("testFileAA").toString(), testPath("testFileA").toString(), testPath("testFileBB").toString()));
    assertThat(matchResults, hasSize(3));
    final List<MatchResult> expected = ImmutableList.of(MatchResult.create(Status.OK, ImmutableList.of(Metadata.builder().setResourceId(testPath("testFileAA")).setIsReadSeekEfficient(true).setSizeBytes("testDataAA".getBytes(StandardCharsets.UTF_8).length).build())), MatchResult.create(Status.NOT_FOUND, ImmutableList.of()), MatchResult.create(Status.OK, ImmutableList.of(Metadata.builder().setResourceId(testPath("testFileBB")).setIsReadSeekEfficient(true).setSizeBytes("testDataBB".getBytes(StandardCharsets.UTF_8).length).build())));
    assertThat(matchResults, equalTo(expected));
}

