@Test
public void testCheckpointMark() throws Exception {
    // we are using no prefetch here
    // prefetch is an ActiveMQ feature: to make efficient use of network resources the broker
    // utilizes a 'push' model to dispatch messages to consumers. However, in the case of our
    // test, it means that we can have some latency between the receiveNoWait() method used by
    // the consumer and the prefetch buffer populated by the broker. Using a prefetch to 0 means
    // that the consumer will poll for message, which is exactly what we want for the test.
    Connection connection = connectionFactoryWithoutPrefetch.createConnection(USERNAME, PASSWORD);
    connection.start();
    Session session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
    MessageProducer producer = session.createProducer(session.createQueue(QUEUE));
    for (int i = 0; i < 10; i++) {
        producer.send(session.createTextMessage("test " + i));
    }
    producer.close();
    session.close();
    connection.close();
    JmsIO.Read spec = JmsIO.read().withConnectionFactory(connectionFactoryWithoutPrefetch).withUsername(USERNAME).withPassword(PASSWORD).withQueue(QUEUE);
    JmsIO.UnboundedJmsSource source = new JmsIO.UnboundedJmsSource(spec);
    JmsIO.UnboundedJmsReader reader = source.createReader(null, null);
    // start the reader and move to the first record
    assertTrue(reader.start());
    // consume 3 messages (NB: start already consumed the first message)
    for (int i = 0; i < 3; i++) {
        assertTrue(reader.advance());
    }
    // the messages are still pending in the queue (no ACK yet)
    assertEquals(10, count(QUEUE));
    // we finalize the checkpoint
    reader.getCheckpointMark().finalizeCheckpoint();
    // the checkpoint finalize ack the messages, and so they are not pending in the queue anymore
    assertEquals(6, count(QUEUE));
    // we read the 6 pending messages
    for (int i = 0; i < 6; i++) {
        assertTrue(reader.advance());
    }
    // still 6 pending messages as we didn't finalize the checkpoint
    assertEquals(6, count(QUEUE));
    // we finalize the checkpoint: no more message in the queue
    reader.getCheckpointMark().finalizeCheckpoint();
    assertEquals(0, count(QUEUE));
}

@Test
public void testCustomTimestampPolicyWithLimitedDelay() {
    // Verifies that max delay is applies appropriately for reporting watermark
    Duration maxDelay = Duration.standardSeconds(60);
    CustomTimestampPolicyWithLimitedDelay<String, String> policy = new CustomTimestampPolicyWithLimitedDelay<>((record -> new Instant(record.getTimestamp())), maxDelay, Optional.empty());
    Instant now = Instant.now();
    TimestampPolicy.PartitionContext ctx = mock(TimestampPolicy.PartitionContext.class);
    when(ctx.getMessageBacklog()).thenReturn(100L);
    when(ctx.getBacklogCheckTime()).thenReturn(now);
    assertThat(policy.getWatermark(ctx), is(BoundedWindow.TIMESTAMP_MIN_VALUE));
    // (1) Test simple case : watermark == max_timesatmp - max_delay
    List<Long> input = ImmutableList.of(// <<< Max timestamp
    -200_000L, // <<< Max timestamp
    -150_000L, // <<< Max timestamp
    -120_000L, // <<< Max timestamp
    -140_000L, // <<< Max timestamp
    -100_000L, -110_000L);
    assertThat(getTimestampsForRecords(policy, now, input), is(input));
    // Watermark should be max_timestamp - maxDelay
    assertThat(policy.getWatermark(ctx), is(now.minus(Duration.standardSeconds(100)).minus(maxDelay)));
    // (2) Verify future timestamps
    input = ImmutableList.of(// <<< timestamp is in future
    -200_000L, // <<< timestamp is in future
    -150_000L, // <<< timestamp is in future
    -120_000L, // <<< timestamp is in future
    -140_000L, // <<< timestamp is in future
    100_000L, -100_000L, -110_000L);
    assertThat(getTimestampsForRecords(policy, now, input), is(input));
    // Watermark should be now - max_delay (backlog in context still non zero)
    assertThat(policy.getWatermark(ctx, now), is(now.minus(maxDelay)));
    // (3) Verify that Watermark advances when there is no backlog
    // advance current time by 5 minutes
    now = now.plus(Duration.standardMinutes(5));
    Instant backlogCheckTime = now.minus(Duration.standardSeconds(10));
    when(ctx.getMessageBacklog()).thenReturn(0L);
    when(ctx.getBacklogCheckTime()).thenReturn(backlogCheckTime);
    assertThat(policy.getWatermark(ctx, now), is(backlogCheckTime.minus(maxDelay)));
}

