@Test
public void testWriteThenRead() throws Exception {
    Instant now = Instant.now();
    List<byte[]> inputData = prepareData();
    // Write data into stream
    p.apply(Create.of(inputData)).apply(KinesisIO.write().withStreamName(options.getAwsKinesisStream()).withPartitioner(new RandomPartitioner()).withAWSClientsProvider(options.getAwsAccessKey(), options.getAwsSecretKey(), Regions.fromName(options.getAwsKinesisRegion())));
    p.run().waitUntilFinish();
    // Read new data from stream that was just written before
    PCollection<byte[]> output = p2.apply(KinesisIO.read().withStreamName(options.getAwsKinesisStream()).withAWSClientsProvider(options.getAwsAccessKey(), options.getAwsSecretKey(), Regions.fromName(options.getAwsKinesisRegion())).withMaxNumRecords(inputData.size()).// to prevent endless running in case of error
    withMaxReadTime(Duration.standardMinutes(5)).withInitialPositionInStream(InitialPositionInStream.AT_TIMESTAMP).withInitialTimestampInStream(now).withRequestRecordsLimit(1000)).apply(ParDo.of(new DoFn<KinesisRecord, byte[]>() {

        @ProcessElement
        public void processElement(ProcessContext c) {
            KinesisRecord record = c.element();
            byte[] data = record.getData().array();
            c.output(data);
        }
    }));
    PAssert.that(output).containsInAnyOrder(inputData);
    p2.run().waitUntilFinish();
}

